export const DEFAULT_COUNTRY: CountryItem = COUNTRIES.find((c) => c.code === "IN") || {
  code: "IN",
  name: "India",
  dialCode: "+91",
  flag: "🇮🇳",
  priority: 1,
  aliases: ["Bharat", "IND"]
};

export function findCountryByCode(code?: string | null): CountryItem {
  if (!code) return DEFAULT_COUNTRY;
  const target = code.trim().toUpperCase();
  return COUNTRIES.find((c) => c.code === target) || DEFAULT_COUNTRY;
}

export function formatCountryOption(country: CountryItem): string {
  return `${country.name} ${country.dialCode}`;
}

export function searchCountries(query: string): CountryItem[] {
  const q = query.trim().toLowerCase();
  if (!q) return COUNTRIES;

  const normalizedQ = q.startsWith("+") ? q.slice(1) : q;

  const matches = COUNTRIES.filter((c) => {
    // 1. Direct country name match
    if (c.name.toLowerCase().includes(q)) return true;

    // 2. ISO country code / abbreviation match (e.g. "SA", "IN", "US")
    if (c.code.toLowerCase().includes(q)) return true;

    // 3. Dial code match (e.g. "+966", "966", "+91", "91")
    const rawDial = c.dialCode.replace("+", "");
    if (c.dialCode.includes(q) || rawDial.startsWith(normalizedQ)) return true;

    // 4. Aliases match (e.g. "UAE", "UK", "USA")
    if (c.aliases && c.aliases.some((a) => a.toLowerCase().includes(q))) return true;

    return false;
  });

  return matches.sort((a, b) => {
    // Exact code match first (e.g. "IN" -> India)
    const aCodeExact = a.code.toLowerCase() === q;
    const bCodeExact = b.code.toLowerCase() === q;
    if (aCodeExact !== bCodeExact) return aCodeExact ? -1 : 1;

    // Exact dial code match second (e.g. "+966" or "966")
    const aDialExact = a.dialCode === q || a.dialCode.replace("+", "") === normalizedQ;
    const bDialExact = b.dialCode === q || b.dialCode.replace("+", "") === normalizedQ;
    if (aDialExact !== bDialExact) return aDialExact ? -1 : 1;

    // Starts with name third
    const aNameStarts = a.name.toLowerCase().startsWith(q);
    const bNameStarts = b.name.toLowerCase().startsWith(q);
    if (aNameStarts !== bNameStarts) return aNameStarts ? -1 : 1;

    // Priority rank
    if (a.priority !== b.priority) return a.priority - b.priority;

    return a.name.localeCompare(b.name);
  });
}

/**
 * Finds country and extracts local national number from an arbitrary phone string.
 * Supports numbers formatted like "+966 51 234 5678", "+966512345678", "+919876543210", etc.
 */
export function findCountryByPhone(rawPhone?: string | null): { country: CountryItem; nationalNumber: string } | null {
  if (!rawPhone) return null;
  const clean = String(rawPhone).trim();
  if (!clean) return null;

  const digits = clean.replace(/[^0-9]/g, "");
  if (!digits) return null;

  // Sort countries by dialCode length descending, then by priority ascending
  const sorted = [...COUNTRIES].sort((a, b) => {
    const lenDiff = b.dialCode.length - a.dialCode.length;
    if (lenDiff !== 0) return lenDiff;
    if (a.priority !== b.priority) return a.priority - b.priority;
    return a.name.localeCompare(b.name);
  });

  const hasExplicitPrefix = clean.startsWith("+") || clean.startsWith("00");
  const pureDigits = clean.startsWith("00") ? digits.slice(2) : digits;

  if (hasExplicitPrefix) {
    for (const c of sorted) {
      const cDigits = c.dialCode.replace("+", "");
      if (pureDigits.startsWith(cDigits)) {
        const national = pureDigits.slice(cDigits.length);
        return { country: c, nationalNumber: national };
      }
    }
  }

  // Non-prefixed numbers: check if it matches a known multi-digit international calling code
  // e.g. 966512345678 (12 digits for Saudi Arabia)
  for (const c of sorted) {
    const cDigits = c.dialCode.replace("+", "");
    if (cDigits !== "1" && cDigits !== "91" && pureDigits.startsWith(cDigits) && pureDigits.length >= 10) {
      return { country: c, nationalNumber: pureDigits.slice(cDigits.length) };
    }
  }

  // Fallback for Indian 10-digit number or 12-digit 91-prefixed number
  if (pureDigits.length === 12 && pureDigits.startsWith("91")) {
    return { country: DEFAULT_COUNTRY, nationalNumber: pureDigits.slice(2) };
  }
  if (pureDigits.length === 10) {
    return { country: DEFAULT_COUNTRY, nationalNumber: pureDigits };
  }

  return null;
}

/**
 * Strips duplicate dial codes and trunk prefixes from user-entered national numbers.
 */
  export function cleanNationalNumber(input: string, dialCode: string = ""): string {
    if (!input) return "";
    let cleaned = input.trim();

    const dialDigits = dialCode.replace(/[^0-9]/g, "");

    // If user pasted or typed with leading + or 00
    if (cleaned.startsWith("+")) {
      cleaned = cleaned.slice(1);
    } else if (cleaned.startsWith("00")) {
      cleaned = cleaned.slice(2);
    }

    // Strip leading dial digits if duplicated
    const onlyDigits = cleaned.replace(/[^0-9]/g, "");
    if (dialDigits && onlyDigits.startsWith(dialDigits) && onlyDigits.length > dialDigits.length + 5) {
      cleaned = onlyDigits.slice(dialDigits.length);
    } else {
      cleaned = onlyDigits;
    }

    // Strip leading domestic trunk 0 if not sole digit
    if (cleaned.startsWith("0") && cleaned.length >= 8) {
      cleaned = cleaned.slice(1);
    }

    return cleaned;
  }
